def build():
    rows=json.loads((OUT/'cases.json').read_text())
    groups={k:set(map(int,v.split())) for k,v in GROUPS.items()}
    result=[]
    for r in rows:
        n=r['case'];codes=[k for k,v in groups.items() if n in v]
        if not codes:raise ValueError(f'Unclassified case {n}')
        stage=next(s for s in STAGES if s[0]<=n<=s[1])
        previous=r['previous_final'];prior_user=rows[n-2] if n>1 else None
        distinct_handoff=bool(previous and (not prior_user or previous['timestamp']>prior_user['timestamp']))
        if 'H' in codes and not distinct_handoff:raise ValueError(f'H without fresh handoff: {n}')
        reason_codes=[k for k in codes if k not in ('G','R','I')] or codes
        result.append({'case':n,'message_id':r['id'],'turn_id':r['turn_id'],'timestamp':r['timestamp'],'source_byte_offset':r['source_byte_offset'],'message_index':r['message_index'],'stage':stage[2],'lesson':stage[3],'labels':[LABELS[k][0] for k in codes], 'reason':NOTES.get(n,'; '.join(LABELS[k][1] for k in reason_codes)), 'prior_final_id':previous['id'] if previous else None,'fresh_final_since_prior_input':distinct_handoff,'avoidable_final_id':previous['id'] if 'H' in codes else None,'confidence':'medium' if n in (3,8,24,37,39,43,112,120,121,132,134,137,156,234) else 'high','excerpt':r['text'].split('## My request:')[-1].strip()[:260].replace('\n',' ')})
    counts=collections.Counter(k for r in result for k in r['labels'])
    report={'method':'Manual retrospective multi-label review; prior/following handoffs linked in local capture. Not independent ground truth or inferred time saved. Early best-process judgments are not retroactive policy violations.', 'capture_sha256':hashlib.sha256((OUT/'history.json').read_bytes()).hexdigest(),'labels':{v[0]:v[1] for v in LABELS.values()},'counts':dict(counts),'human_inputs':len(result)-counts['system_handoff'],'distinct_avoidable_final_ids':len({r['avoidable_final_id'] for r in result if r['avoidable_final_id']}),'cases':result}
    dest=ROOT/'docs/knowledge/PASHTUN_PRODUCTION_AUDIT250_CASES.json'
    dest.write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps({k:v for k,v in report.items() if k not in ('cases','labels')},indent=2))

if __name__=='__main__':build()
